<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';requireLogin();$q=$pdo->prepare('SELECT * FROM pesanan WHERE id_user=:user ORDER BY COALESCE(created_at,tanggal) DESC,id_pesanan DESC');$q->execute(['user'=>$_SESSION['id_user']]);$orders=$q->fetchAll();$steps=['menunggu_pembayaran','menunggu_verifikasi','diproses','dikirim','selesai'];$pageTitle='Pesanan Saya | MyBuah';require __DIR__.'/includes/header.php';?><section class="container page-shell section"><div class="breadcrumb">Katalog / Pesanan Saya</div><div class="section-heading"><h1>Lacak Pesanan</h1></div><?php if(isset($_GET['baru'])):?><div class="form-success">✓ Pembayaran berhasil dikirim, menunggu verifikasi admin.</div><?php endif;?><?php if(!$orders):?><div class="empty-state">Belum ada pesanan.</div><?php else:?><div class="order-list"><?php foreach($orders as $order):$status=$order['status'];$index=array_search($status,$steps,true);if($index===false)$index=0;$items=json_decode((string)$order['items_json'],true)?:[['nama'=>'Produk','jumlah'=>$order['jumlah_produk']]];?><article class="order-card"><div class="order-header"><span class="order-meta">Pesanan · <?=e($order['tanggal']?:substr((string)$order['created_at'],0,10))?></span><span class="status-badge <?=orderStatusClass($status)?>"><?=orderStatusLabel($status)?></span></div><p class="order-products"><?php $names=[];foreach($items as $item)$names[]=(int)$item['jumlah'].'x '.e($item['nama']);echo implode(', ',$names);?></p><div class="stepper"><?php foreach(['Menunggu','Diproses','Dikirim','Diterima'] as $n=>$label):?><div class="step <?=$n<$index?'done':($n===$index?'current':'')?>" data-step="<?=$n+1?>"><?=$label?></div><?php endforeach;?></div><div class="order-footer"><span>Total Pesanan</span><strong class="order-total"><?=formatRupiah($order['total'])?></strong></div></article><?php endforeach;?></div><?php endif;?></section><?php require __DIR__.'/includes/footer.php';